// The caller reads the rows directly: each row is one colleague of $of.
query colleagues($of: String) {
    match {
        $p: Person { handle: $of }
        $p worksAt $c
        $q worksAt $c
        $q.handle != $p.handle
    }
    return { $q.handle, $q.name }
}
```

```gq
// GQ has no way to call one query from another, so this repeats the colleagues
// pattern twice. The caller reads the distinct names directly. The result can
// include $of's own name, since $of is a colleague of each of their colleagues.
query colleagues_of_colleagues($of: String) {
    match {
        $p: Person { handle: $of }
        $p worksAt $c
        $m worksAt $c
        $m.handle != $p.handle
        $m worksAt $c2
        $r worksAt $c2
        $r.handle != $m.handle
    }
    return distinct { $r.name }
}
